<span class="line"><span style="color:#ABB2BF;">            schedule.resource_timelines[res.resource_id] </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> ResourceTimeline</span><span style="color:#ABB2BF;">(res.resource_id)</span></span>
