<span class="line"><span style="color:#ABB2BF;">            optimistic_bound </span><span style="color:#56B6C2;">=</span><span style="color:#E5C07B;"> self</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">estimate_optimistic_bound</span><span style="color:#ABB2BF;">(remaining_ops)</span></span>
