<span class="line"><span style="color:#ABB2BF;">                results[idx] </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> future.</span><span style="color:#61AFEF;">result</span><span style="color:#ABB2BF;">()</span></span>
